/**
 * DATABASE SCHEMA
 * ---------------
 * One schema that runs unchanged on SQLite and PostgreSQL.
 *
 * Rules that keep it portable:
 *   - TEXT primary keys (UUIDs generated by the app, not by the database)
 *   - TEXT ISO-8601 timestamps
 *   - No engine-specific column types beyond TEXT / INTEGER / REAL
 *   - `ON CONFLICT (...) DO ...` works on SQLite 3.24+ and PostgreSQL 9.5+
 */

export const SCHEMA_SQL = `
CREATE TABLE IF NOT EXISTS users (
  id                  TEXT PRIMARY KEY,
  username            TEXT NOT NULL,
  username_lower      TEXT NOT NULL UNIQUE,
  email               TEXT NOT NULL,
  email_lower         TEXT NOT NULL UNIQUE,
  password_hash       TEXT,
  avatar              TEXT,
  friend_code         TEXT NOT NULL UNIQUE,
  face_auth_enabled   INTEGER NOT NULL DEFAULT 0,
  face_embedding      TEXT,
  biometric_consent_at TEXT,
  created_at          TEXT NOT NULL,
  current_streak      INTEGER NOT NULL DEFAULT 0,
  longest_streak      INTEGER NOT NULL DEFAULT 0,
  lifetime_pushups    INTEGER NOT NULL DEFAULT 0,
  personal_best       INTEGER NOT NULL DEFAULT 0,
  avg_daily_pushups   REAL NOT NULL DEFAULT 0,
  active_days         INTEGER NOT NULL DEFAULT 0,
  last_workout_date   TEXT,
  onboarded           INTEGER NOT NULL DEFAULT 0,
  notify_enabled      INTEGER NOT NULL DEFAULT 1,
  notify_frequency    TEXT NOT NULL DEFAULT 'normal',
  deleted_at          TEXT
);

CREATE INDEX IF NOT EXISTS idx_users_friend_code ON users (friend_code);

CREATE TABLE IF NOT EXISTS auth_sessions (
  id          TEXT PRIMARY KEY,
  user_id     TEXT NOT NULL,
  token_hash  TEXT NOT NULL UNIQUE,
  created_at  TEXT NOT NULL,
  expires_at  TEXT NOT NULL,
  user_agent  TEXT
);

CREATE INDEX IF NOT EXISTS idx_auth_sessions_user ON auth_sessions (user_id);

CREATE TABLE IF NOT EXISTS webauthn_credentials (
  id            TEXT PRIMARY KEY,
  user_id       TEXT NOT NULL,
  credential_id TEXT NOT NULL UNIQUE,
  public_key    TEXT NOT NULL,
  counter       INTEGER NOT NULL DEFAULT 0,
  transports    TEXT,
  device_type   TEXT,
  backed_up     INTEGER NOT NULL DEFAULT 0,
  label         TEXT,
  created_at    TEXT NOT NULL,
  last_used_at  TEXT
);

CREATE INDEX IF NOT EXISTS idx_webauthn_user ON webauthn_credentials (user_id);

CREATE TABLE IF NOT EXISTS webauthn_challenges (
  id          TEXT PRIMARY KEY,
  user_id     TEXT,
  challenge   TEXT NOT NULL,
  kind        TEXT NOT NULL,
  created_at  TEXT NOT NULL,
  expires_at  TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS friendships (
  id            TEXT PRIMARY KEY,
  requester_id  TEXT NOT NULL,
  recipient_id  TEXT NOT NULL,
  status        TEXT NOT NULL DEFAULT 'pending',
  blocked_by    TEXT,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_friendships_req ON friendships (requester_id);
CREATE INDEX IF NOT EXISTS idx_friendships_rec ON friendships (recipient_id);

CREATE TABLE IF NOT EXISTS workout_sessions (
  id               TEXT PRIMARY KEY,
  user_id          TEXT NOT NULL,
  started_at       TEXT NOT NULL,
  ended_at         TEXT NOT NULL,
  day_key          TEXT NOT NULL,
  pushup_count     INTEGER NOT NULL DEFAULT 0,
  invalid_count    INTEGER NOT NULL DEFAULT 0,
  validation_score REAL NOT NULL DEFAULT 0,
  duration_ms      INTEGER NOT NULL DEFAULT 0,
  device           TEXT,
  flagged          INTEGER NOT NULL DEFAULT 0,
  created_at       TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_sessions_user_day ON workout_sessions (user_id, day_key);

CREATE TABLE IF NOT EXISTS daily_stats (
  id            TEXT PRIMARY KEY,
  user_id       TEXT NOT NULL,
  day_key       TEXT NOT NULL,
  pushup_count  INTEGER NOT NULL DEFAULT 0,
  session_count INTEGER NOT NULL DEFAULT 0,
  avg_confidence REAL NOT NULL DEFAULT 0,
  updated_at    TEXT NOT NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_daily_user_day ON daily_stats (user_id, day_key);

CREATE TABLE IF NOT EXISTS challenges (
  id          TEXT PRIMARY KEY,
  creator_id  TEXT NOT NULL,
  name        TEXT NOT NULL,
  description TEXT,
  type        TEXT NOT NULL DEFAULT 'total',
  target      INTEGER,
  start_date  TEXT NOT NULL,
  end_date    TEXT NOT NULL,
  created_at  TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS challenge_participants (
  id           TEXT PRIMARY KEY,
  challenge_id TEXT NOT NULL,
  user_id      TEXT NOT NULL,
  pushup_count INTEGER NOT NULL DEFAULT 0,
  joined_at    TEXT NOT NULL,
  last_synced_session TEXT
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_challenge_user ON challenge_participants (challenge_id, user_id);

CREATE TABLE IF NOT EXISTS achievements (
  id          TEXT PRIMARY KEY,
  code        TEXT NOT NULL UNIQUE,
  name        TEXT NOT NULL,
  description TEXT NOT NULL,
  icon        TEXT NOT NULL,
  kind        TEXT NOT NULL,
  threshold   INTEGER NOT NULL DEFAULT 0,
  sort_order  INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS user_achievements (
  id             TEXT PRIMARY KEY,
  user_id        TEXT NOT NULL,
  achievement_id TEXT NOT NULL,
  unlocked_at    TEXT NOT NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_user_achievement ON user_achievements (user_id, achievement_id);

CREATE TABLE IF NOT EXISTS notifications (
  id         TEXT PRIMARY KEY,
  user_id    TEXT NOT NULL,
  type       TEXT NOT NULL,
  message    TEXT NOT NULL,
  icon       TEXT,
  created_at TEXT NOT NULL,
  read_at    TEXT
);

CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications (user_id, created_at);
`;

/**
 * Achievement catalogue. `kind` tells the unlock checker what to compare:
 *   lifetime  -> users.lifetime_pushups
 *   streak    -> users.current_streak
 *   daily     -> users.personal_best (best single day)
 *   friends   -> number of accepted friends beaten on lifetime totals
 *   sessions  -> total number of completed workout sessions
 */
